CREATE TABLE DBP_DATA.CHARGE_SOLL (
   mandant_id                          INTEGER    NOT NULL COMMENT 'Mandant im DWH',
   charge_id                           VARCHAR(10)     collate 'en-ci'   NOT NULL COMMENT 'Chargennummer, analog zu qa_check_og.charge_id - Feld CHARG',
   gp_id                               INTEGER    NOT NULL COMMENT 'Kontonummer des Lieferanten bzw. Kreditors - Feld LIFNR',
   art_id                              INTEGER    NOT NULL COMMENT 'Artikelnummer - Feld MATNR',
   dat_von                             DATE            COMMENT 'Sagt aus, ab wann die Charge mit den angegebenen Informationen gültig ist. Eine Charge kann sich im Laufe der Bestellung ändern, dann wird eine neue Chargennummer angelegt - sie wird also neu angelegt und nicht begrenzt. - Feld GILTAB',
   ursprungsland_kbez_soll             VARCHAR(4)      collate 'en-ci' COMMENT 'Ursprungsland/Länderschlüssel, bspw. DE oder NZ - Feld URZLA',
   zus_ursprungslaender_kbez_soll      VARCHAR(16)     collate 'en-ci' COMMENT 'weitere Ursprungslänger/Sign O+G, bspw. BE, GR oder NL - Feld SIGNO',
   kollifaktor                         NUMBER(29,3)    COMMENT 'Kollifaktor, bspw. 10,000 oder 8,000, ist im SOLL (ZOG_CHAR) und IST (ZLV_QA_OG_ACT) identisch - Feld KOLLI',
   palettenfaktor_soll                 INTEGER    COMMENT 'Pallettenfaktor/Menge in Paletten, bspw. 100 oder 60 - Feld MENGEP',
   kontrollnotwendigkeit_vorerntenummer_soll_fg INTEGER    DEFAULT 0 NOT NULL COMMENT 'Flag für QS, sagt aus ob Vorerntenummer kontrolliert werden soll - Feld VORERNTE',
   vertragsanbau_soll_fg               INTEGER    DEFAULT 0 NOT NULL COMMENT 'Flag das aussagt, ob es Vertragsanbau geben soll - Feld CONTRACT_FRAMING',
   nationale_produktion_soll_fg        INTEGER    DEFAULT 0 NOT NULL COMMENT 'Flag das aussagt, ob Produkt einer nationalen Produktion unterliegen soll - Feld NATIONAL_PROD',
   handelsklasse_soll_kz               VARCHAR(1)      collate 'en-ci' COMMENT 'Information zur Handelsklasse, bspw. 0  für HKL0, 1 für HKL1,… - Feld HKL',
   unbehandelt_soll_kz                 VARCHAR(1)      collate 'en-ci' COMMENT 'KZ das angibt, ob O&G behandelt oder unbehandelt sein soll, bspw. U für unbehandelt - Feld KZBEH',
   transport_verpackung_kmo_soll_kz    VARCHAR(2)      collate 'en-ci' COMMENT 'Zweistelliges KZ über Transportverpackung, bspw. KA für Karton - Feld KZPACK',
   kaliber_von_soll                    INTEGER    COMMENT 'Kaliber, Größe, Gewicht von, bspw. 800 - Feld KALVON',
   kaliber_bis_soll                    INTEGER    COMMENT 'Kaliber, Größe, Gewicht bis, bspw. 1000 - Feld KALBIS',
   einh_id                             VARCHAR(3)      collate 'en-ci'  NOT NULL COMMENT '(Bestellmengen-)Einheit, bspw. ST oder KG - Feld BSTME',
   freitext_besonderheiten_soll        VARCHAR(30)     collate 'en-ci'  COMMENT 'Freitextfeld: Besonderheiten (SOLL), z.B. bei einer Mango - Ist sie vorgereift? Kann das Stück auch mal mehr als 250 Gramm haben? - Feld TEXT',
   freitext_transport_verpackung_de_soll VARCHAR(15)   collate 'en-ci'   COMMENT 'Freitextfeld: Transportverpackung, nur für DE gefüllt, bspw. LIN oder KARTON - Feld VERPACKTRANS',
   gp_charge_nr                        VARCHAR(20)     collate 'en-ci'  COMMENT 'Lieferantenchargennummer, unterscheidet sich von der KFL Chargennummer charge_id, ist im SOLL (ZOG_CHAR) und IST (ZLV_QA_OG_ACT) identisch - Feld LICHN',
   gtin_fg                             INTEGER    DEFAULT 0 NOT NULL COMMENT 'Flag das aussagt, ob eine GTIN vorhanden ist, ist im SOLL (ZOG_CHAR) und IST (ZLV_QA_OG_ACT) identisch - Feld GTIN_VORHANDEN',
   charge_vorhanden_soll_fg            INTEGER    DEFAULT 0 NOT NULL COMMENT 'Flag das aussagt, ob eine Charge vorhanden sein soll - Feld CHARGE_VORHANDEN',
   freitext_temperatur_check_soll      VARCHAR(20)     collate 'en-ci'  COMMENT 'Freitextfeld: Temperatur mit der die Ware ankommen soll - Feld TEMPERATURE',
   freitext_fruchtfleischdruck_soll    VARCHAR(30)     collate 'en-ci'  COMMENT 'Freitextfeld: Sagt aus, wie fest Fruchtfleisch sein soll wenn man die Frucht eindrückt - Feld DRUCK (SAP-Feld wurde früher für etwas anderes genutzt (früher wurden Preise auf das Etikett angedrückt), Feldname wurde in SAP nie angepasst)',
   freitext_saftgehalt_soll            VARCHAR(30)     collate 'en-ci'  COMMENT 'Freitextfeld: Sagt etwas über den Saftgehalt des Artikels aus - Feld REGIONAL_PACK (SAP-Feld wurde früher für etwas anderes genutzt, Feldname wurde in SAP nie angepasst)',
   freitext_lieferanten_kommentar_soll VARCHAR(180)    collate 'en-ci'  COMMENT 'Freitextfeld: Information für den Lieferant (SOLL) - Feld KOMMENTAR_LIEFERANT',
   nettoinhalt_kolli_soll              NUMBER(29,3)    COMMENT 'Freitextfeld: Durchführung Stichprobe (SOLL) - Sind in 500g Schale auch 500g enthalten? Bei Artikeln ohne Prüfmöglichkeit/Prüfung steht hier eine 0 - Feld NTGEW',
   freitext_primaerverpackung_soll     VARCHAR(30)     collate 'en-ci'  COMMENT 'Freitextfeld: Verpackung, wie sie im Laden für den Kunden stehen soll - Feld KUNDEN_PACK',
   freitext_qa_kommentar_soll          VARCHAR(180)    collate 'en-ci'  COMMENT 'Freitextfeld: Information für den Einkauf - Feld KOMMENTAR_QS',
   freitext_marke_soll                 VARCHAR(60)     collate 'en-ci' COMMENT 'Freitextfeld: Marke des Artikels (SOLL) - Feld MARKE',
   freitext_fruchtgehalt_soll          VARCHAR(20)      collate 'en-ci'  COMMENT 'Freitextfeld: Zuckergehalt des Artikels - Feld SALES_UNIT',
   kaliber_kz_soll                     VARCHAR(4)      collate 'en-ci'  COMMENT 'Kaliber des Produktes SOLL: Größe, Gewicht o.Ä. - Feld CALIBER_UNIT',
   freitext_spezifikation_soll         VARCHAR(110)    collate 'en-ci'  COMMENT 'Freitextfeld: Spezifikation - Feld Spezifikation'
   ,TD_UPDATE 	TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration'
   ,TD_INSERT 	TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration'
)COMMENT = 'SAP RET INT ZOG_CHAR - enthält die O&G Chargenwerte, die durch den EK definiert und bestellt wurden (SOLL), z.B. Äpfel in der Größe 80mm - ZLV_QA_OG_ACT bzw. charge_ist_qa_og bildet das IST ab';
